/* 送出 for the describer review pages (review/<clip>-<half>/review_pilot.html).
 *
 * The review pages were generated by `gapcaster review --pilot` and patched on 23 November 2026:
 * a 送出記錄 button, a status line, and one short function in the page's own script,
 * window.GCReviewLog(), which runs the same checks as 完成並下載 (code filled in, confirm unmarked
 * or unfixed lines), stops the timer and returns the same pilot_log object the download holds.
 * This file posts that object to the trial inbox with GC.send (assets/common.js), only when the
 * describer presses 送出記錄. 完成並下載 pilot_log.json stays as the fallback.
 *
 * The page name sent with the log records the clip half and the counterbalancing row, e.g.
 * "review-pilot-1 A-1 row2": from the link (row=N, set by kit.html) or, for an open code, from the
 * code itself (GC.rowForCode). An open code with no consent record on this device gets the five
 * consent items next to the button (GC.consentGate) and is not sent until they are ticked.
 */
(function () {
  "use strict";
  var GC = window.GC;
  var btn = document.getElementById("btn-send");
  if (!GC || !btn) return;

  // review/A-2/review_pilot.html -> clip A, half 2.
  var m = /\/review\/([AB])-([12])\//.exec(window.location.pathname);
  var detail = m ? m[1] + m[2] : "";
  var basePage = (document.body.getAttribute("data-page") || "review-pilot") + (m ? " " + m[1] + "-" + m[2] : "");
  var pcode = document.getElementById("pcode");
  var params = GC.readParams();
  var linkRow = /^[1-4]$/.test(params.row || "") ? Number(params.row) : null;

  function currentCode() { return GC.cleanCode(pcode ? pcode.value : ""); }
  function rowOf(code) { return GC.isOpenCode(code) ? GC.rowForCode(code) : linkRow; }

  var gate = GC.consentGate({ before: btn.parentNode, root: "../../", boxClass: "whint" });

  var ui = GC.sendButton({
    button: btn,
    status: document.getElementById("send-status"),
    receipt: document.getElementById("send-receipt"),
    help: document.getElementById("send-help"),
    key: function () {
      var c = currentCode();
      return GC.validCode(c) && detail ? GC.receiptKey("review", c, detail) : "";
    },
    build: function () {
      if (typeof window.GCReviewLog !== "function") {
        return { error: "送出功能沒有載入。請改按「完成並下載 pilot_log.json」，用 email 附件寄給 Ted：tedinroc@gmail.com。" };
      }
      // Check the code's form and the consent record before the page stops the timer.
      var typed = currentCode();
      if (typed && !GC.validCode(typed)) {
        pcode.setAttribute("aria-invalid", "true");
        return { error: GC.CODE_HELP, focus: pcode };
      }
      var g = typed ? gate.check(typed, params.consent) : null;
      if (g) return g;
      var r = window.GCReviewLog();
      if (!r || r.cancel) return { cancel: true };
      if (r.error) return r;
      var code = GC.cleanCode(r.log.participant);
      if (!GC.validCode(code)) {
        return { error: GC.CODE_HELP, focus: pcode };
      }
      var row = rowOf(code);
      var consent = GC.consentFor(code, params.consent);
      return { body: GC.envelope("review", code, basePage + (row ? " row" + row : ""), r.log, consent) };
    }
  });
  function refresh() {
    ui.showReceipt();
    var c = currentCode();
    gate.update(GC.validCode(c) ? c : "", params.consent);
  }
  if (pcode) pcode.addEventListener("input", refresh);
  refresh();
})();
